CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TYPE "user_role" AS ENUM ('owner','staff');
CREATE TYPE "booking_status" AS ENUM ('held','confirmed','in_progress','done','cancelled','no_show');
CREATE TYPE "notification_channel" AS ENUM ('push','sms','whatsapp');
CREATE TABLE "shops" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL, "slug" text NOT NULL UNIQUE, "time_zone" text NOT NULL DEFAULT 'Asia/Karachi', "working_hours" jsonb NOT NULL, "buffer_minutes" integer NOT NULL DEFAULT 5, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "users" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL, "email" text NOT NULL UNIQUE, "password_hash" text NOT NULL, "role" user_role NOT NULL, "shop_id" uuid NOT NULL REFERENCES "shops"("id"), "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "staff" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "shop_id" uuid NOT NULL REFERENCES "shops"("id"), "user_id" uuid REFERENCES "users"("id"), "name" text NOT NULL, "working_hours" jsonb NOT NULL, "breaks" jsonb NOT NULL, "active" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "services" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "shop_id" uuid NOT NULL REFERENCES "shops"("id"), "name" text NOT NULL, "duration_minutes" integer NOT NULL CHECK ("duration_minutes" > 0), "price" numeric(10,2) NOT NULL CHECK ("price" >= 0), "active" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "customers" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL, "phone" text NOT NULL UNIQUE, "phone_verified_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "bookings" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "shop_id" uuid NOT NULL REFERENCES "shops"("id"), "staff_id" uuid NOT NULL REFERENCES "staff"("id"), "customer_id" uuid NOT NULL REFERENCES "customers"("id"), "ticket_number" text NOT NULL, "start_at" timestamptz NOT NULL, "end_at" timestamptz NOT NULL, "actual_start_at" timestamptz, "actual_end_at" timestamptz, "status" booking_status NOT NULL DEFAULT 'held', "hold_expires_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), CHECK ("end_at" > "start_at"), UNIQUE("shop_id","ticket_number"));
ALTER TABLE "bookings" ADD CONSTRAINT "bookings_no_active_staff_overlap" EXCLUDE USING gist ("staff_id" WITH =, tstzrange("start_at", "end_at", '[)') WITH &&) WHERE ("status" IN ('held','confirmed','in_progress'));
CREATE TABLE "booking_services" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "booking_id" uuid NOT NULL REFERENCES "bookings"("id"), "service_id" uuid NOT NULL REFERENCES "services"("id"), "service_name" text NOT NULL, "duration_minutes" integer NOT NULL, "price" numeric(10,2) NOT NULL);
CREATE TABLE "notifications" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "booking_id" uuid NOT NULL REFERENCES "bookings"("id"), "type" text NOT NULL, "channel" notification_channel NOT NULL, "sent_at" timestamptz, "status" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now());
